import { slugify } from "@curiousleaf/utils"
import { db } from "@openalternative/db"
import { headers } from "next/headers"
import { createServerAction } from "zsa"
import { subscribeToNewsletter } from "~/actions/subscribe"
import { auth } from "~/lib/auth"
import { getIP, isRateLimited } from "~/lib/rate-limiter"
import { submitToolSchema } from "~/server/schemas"
import { inngest } from "~/services/inngest"
import { isDisposableEmail } from "~/utils/helpers"

/**
 * Generates a unique slug by adding a numeric suffix if needed
 */
const generateUniqueSlug = async (baseName: string): Promise<string> => {
  const baseSlug = slugify(baseName)
  let slug = baseSlug
  let suffix = 2

  while (true) {
    // Check if slug exists
    if (!(await db.tool.findUnique({ where: { slug } }))) {
      return slug
    }

    // Add/increment suffix and try again
    slug = `${baseSlug}-${suffix}`
    suffix++
  }
}

/**
 * Submit a tool to the database
 * @param input - The tool data to submit
 * @returns The tool that was submitted
 */
export const submitTool = createServerAction()
  .input(submitToolSchema)
  .handler(async ({ input: { newsletterOptIn, ...data } }) => {
    const session = await auth.api.getSession({ headers: await headers() })

    if (!session?.user) {
      const ip = await getIP()

      // Rate limiting check
      if (await isRateLimited(ip, "submission")) {
        throw new Error("Too many submissions. Please try again later.")
      }

      // Disposable email check
      if (await isDisposableEmail(data.submitterEmail)) {
        throw new Error("Invalid email address, please use a real one")
      }
    }

    if (newsletterOptIn) {
      await subscribeToNewsletter({
        value: data.submitterEmail,
        utm_medium: "submit_form",
        send_welcome_email: false,
      })
    }

    // Check if the tool already exists
    const existingTool = await db.tool.findFirst({
      where: { OR: [{ repositoryUrl: data.repositoryUrl }, { websiteUrl: data.websiteUrl }] },
    })

    // If the tool exists, redirect to the tool or submit page
    if (existingTool) {
      return existingTool
    }

    // Generate a unique slug
    const slug = await generateUniqueSlug(data.name)

    // Save the tool to the database
    const tool = await db.tool.create({
      data: { ...data, slug, ownerId: session?.user.id },
    })

    // Send an event to the Inngest pipeline
    await inngest.send({ name: "tool.submitted", data: { slug } }).then(async () => {
      await inngest.send({ name: "tool.expedited", data: { slug: tool.slug } })
    })

    return tool
  })

"use server"

import wretch from "wretch"
import { createServerAction } from "zsa"
import { env } from "~/env"
import { getIP, isRateLimited } from "~/lib/rate-limiter"
import { newsletterSchema } from "~/server/schemas"
import { isDisposableEmail, tryCatch } from "~/utils/helpers"

/**
 * Subscribe to the newsletter
 * @param input - The newsletter data to subscribe to
 * @returns The newsletter that was subscribed to
 */
export const subscribeToNewsletter = createServerAction()
  .input(newsletterSchema)
  .handler(async ({ input: { value: email, ...input } }) => {
    const ip = await getIP()

    // Rate limiting check
    if (await isRateLimited(ip, "newsletter")) {
      throw new Error("Too many attempts. Please try again later.")
    }

    // Disposable email check
    if (await isDisposableEmail(email)) {
      throw new Error("Invalid email address, please use a real one")
    }

    const url = `https://api.beehiiv.com/v2/publications/${env.BEEHIIV_PUBLICATION_ID}/subscriptions`

    const { data, error } = await tryCatch(
      wretch(url)
        .auth(`Bearer ${env.BEEHIIV_API_KEY}`)
        .post({ email, ...input })
        .json<{ data: { status: string } }>(),
    )

    if (error) {
      throw new Error("Failed to subscribe to newsletter. Please try again later.")
    }

    if (data.data.status === "pending") {
      return "You've been subscribed to the newsletter, please check your email for confirmation."
    }

    return "You've been subscribed to the newsletter."
  })

